t.script:
function checkPaymentStatus() {
    var transactionRef = '';

    fetch('/payment/status/' + transactionRef, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            var statusElement = document.getElementById('payment-status');
            statusElement.textContent = getStatusText(data.state);

            if (data.state === 'done') {
                // 支付成功，刷新页面
                setTimeout(function() {
                    window.location.reload();
                }, 2000);
            } else if (data.state === 'cancel') {
                // 支付取消
                setTimeout(function() {
                    window.location.reload();
                }, 2000);
            }
        }
    })
    .catch(error => {
        console.error('检查支付状态失败:', error);
    });
}

function getStatusText(state) {
    switch(state) {
        case 'pending': return '等待支付';
        case 'done': return '支付成功';
        case 'cancel': return '支付取消';
        case 'error': return '支付失败';
        default: return '未知状态';
    }
}

// 自动检查支付状态
setInterval(checkPaymentStatus, 5000);

