// 支付宝支付处理
document.addEventListener('DOMContentLoaded', function() {
    var alipayButtons = document.querySelectorAll('button[data-provider-id]');

    alipayButtons.forEach(function(button) {
        button.addEventListener('click', function() {
            var providerId = this.getAttribute('data-provider-id');
            var form = this.closest('form');

            // 获取交易信息
            var transactionData = {
                'provider_id': providerId,
                'amount': form.querySelector('[name="amount"]').value,
                'currency_id': form.querySelector('[name="currency_id"]').value,
                'reference': form.querySelector('[name="reference"]').value,
                'partner_id': form.querySelector('[name="partner_id"]').value,
                'landing_route': form.querySelector('[name="landing_route"]').value
            };

            // 提交支付请求
            fetch('/payment/alipay/payment', {
                method: 'POST',
            .then(data => {
                if (data.success && data.payment_url) {
                    // 跳转到支付宝支付页面
                    window.location.href = data.payment_url;
                } else {
                    alert("支付请求失败: " + (data.message || "未知错误"));
                }
            })
            .catch(error => {
                console.error("支付请求错误:", error);
                alert("支付请求发生错误，请重试");
            });
        });
